SELECT i.id, i.instance_code, i.instance_name, i.model_id, i.project_id, i.instance_status, i.instance_version, i.instance_description, i.instance_config, i.calculation_result, i.last_calculated_at, i.calculation_status, i.creator_id, i.tenant_id, i.created_at, i.updated_at, i.deleted, m.model_name, m.model_code, m.model_description FROM soo_financial_model_instance i LEFT JOIN soo_financial_model m ON i.model_id = m.id WHERE i.deleted = 0
